mapper.select:
SELECT answer_type AS answer_type,
       COUNT(*)    AS cnt
FROM kb_retrieval_log
WHERE tenant_id  = #{tenantId}
  AND kb_id      = #{kbId}
  AND created_at >= #{since}
GROUP BY answer_type

SELECT COUNT(*)
FROM kb_retrieval_log
WHERE tenant_id  = #{tenantId}
  AND kb_id      = #{kbId}
  AND created_at > #{since}

SELECT id, tenant_id, kb_id, session_id, user_id, query, rewritten_query,
       top_chunks, top_score, answer_type, retrieval_ms, rerank_ms,
       generate_ms, total_ms, created_at
FROM kb_retrieval_log
WHERE tenant_id = #{tenantId}
  AND kb_id     = #{kbId}
ORDER BY created_at DESC
LIMIT #{limit}
